-- ============================================================
-- Catlike Reflexes: wiring
-- ============================================================
--
-- TODO.md: "Catlike Reflexes (2, 6): Increases your pet's chance to dodge by
-- 3/6/9%, and when your pet dodges the cooldown on Pack Hunting is reset.
-- Additionally reduces the cooldown of Kill Command by 30 sec. (3 ranks)"
--
-- Effect2 (the pet's +3/6/9% dodge) is already exactly right and is untouched.
--
-- Effect1 was the HUNTER's own +1/2/3% dodge -- a self bonus on a pet talent,
-- and the only free effect slot.  It becomes the spell_pet_auras carrier.
--
-- Effect3 is the interesting one.  It was ALREADY an ADD_FLAT_MODIFIER with
-- MiscValue 11 (SPELLMOD_COOLDOWN) at -10000/-20000/-30000 ms -- retail's own
-- "reduces the cooldown of Kill Command" -- but ALL THREE of its class masks are
-- zero, so it matched nothing and the talent has never done that half at all.
-- Only the mask is fixed here: class mask B 2048 is Kill Command 34026
-- (SpellFamilyFlags1 = 0x800, family 9).  A and C are set to 0 explicitly, which
-- is the `--base` inheritance trap CLAUDE.md warns about -- a stray bit in an
-- unused mask word silently widens or breaks the match.
--
-- This reaches a CATEGORY cooldown, which is the thing worth checking before
-- trusting it: Kill Command has RecoveryTime 0, Category 1171 and
-- CategoryRecoveryTime 60000, so the whole minute is a category cooldown.
-- Player::AddSpellAndCategoryCooldowns (Player.cpp:10988) applies SPELLMOD_COOLDOWN
-- to catrec as well as rec, gated only on SPELL_ATTR6_NO_CATEGORY_COOLDOWN_MODS,
-- which 34026 does not carry.  So -30s at rank 3 lands on a 60s ability.
--
-- The per-rank -10/-20/-30 progression is kept rather than flattened to -30 at
-- every rank: the TODO quotes the max-rank number, and retail already had the
-- ramp.
--
-- One carrier for all three ranks -- there is nothing per-rank about the reset.
DELETE FROM `spell_pet_auras` WHERE `spell` IN (34462, 34464, 34465);
INSERT INTO `spell_pet_auras` (`spell`, `effectId`, `pet`, `aura`) VALUES
(34462, 0, 0, 200755),
(34464, 0, 0, 200755),
(34465, 0, 0, 200755);

-- HitMask 16 (PROC_HIT_DODGE, SpellMgr.h:261) IS the mechanism -- ProcFlags only
-- says "the pet was attacked", and the hit mask is what narrows that to a dodge.
-- TAKEN_* flags because the pet is the victim of the event, not the actor.
--
-- Cooldown 3000: a pet at 9% talent dodge plus Thick Hide's agility conversion
-- dodges often enough that an unthrottled reset would leave Pack Hunting
-- permanently off cooldown, which is not a talent so much as a removal of the
-- ability's cost.
DELETE FROM `spell_proc` WHERE `SpellId` = 200755;
